def moore_bound(delta, g):
    if g % 2 == 1:
        k = (g - 1) // 2
        # 1 + delta * ((delta-1)^k - 1) / (delta-2)
        return 1 + delta * ((delta - 1)**k - 1) // (delta - 2)
    else:
        k = g // 2
        # 2 * ((delta-1)^k - 1) / (delta-2)
        return 2 * ((delta - 1)**k - 1) // (delta - 2)

print(f"Moore bound for delta=3, g=7: {moore_bound(3, 7)}")
print(f"Moore bound for delta=3, g=6: {moore_bound(3, 6)}")
